patch_result.patch:
--- a/valid.c
+++ b/valid.c
@@ -2509,20 +2509,25 @@
 int
 xmlRemoveID(xmlDocPtr doc, xmlAttrPtr attr) {
     xmlIDTablePtr table;
+    xmlIDPtr id;
+    const xmlChar *value;

     if (doc == NULL) return(-1);
     if ((attr == NULL) || (attr->id == NULL)) return(-1);

+    id = attr->id;
+    value = id->value;
+
+    attr->atype = 0;
+    attr->id = NULL;
+
     table = (xmlIDTablePtr) doc->ids;
     if (table == NULL)
         return(-1);

-    if (xmlHashRemoveEntry(table, attr->id->value, xmlFreeIDTableEntry) < 0)
+    if (xmlHashRemoveEntry(table, value, xmlFreeIDTableEntry) < 0)
         return(-1);

-    attr->atype = 0;
-    attr->id = NULL;
-
     return(0);
 }

